import { PrimaryConnectionTarget, BearerConnectionTarget, RelayConnectionTarget, SshConnectionTarget } from "@t3tools/client-runtime/connection";
import { EnvironmentId, buildRemoteOpenUrl } from "@t3tools/contracts";
import { describe, it, expect } from "vite-plus/test";
import { resolveRemoteOpenState } from "./remoteOpen";
const environmentId = EnvironmentId.make("benchmark-v3-synthetic");
const advertised = [{kind: "tailscale", host: "fallback.tail0000.ts.net", username: "dev"}] as const;
const primary = (url: string) => new PrimaryConnectionTarget({environmentId,label:"synthetic",httpBaseUrl:url,wsBaseUrl:url.replace(/^http/,"ws")});
const base = {sshTarget:null,remoteOpenTargets:advertised,isDesktopRenderer:false};
const hostOf = (s: ReturnType<typeof resolveRemoteOpenState>) => s.mode === "remote-links" ? s.host.host.replace(/^\[|\]$/g, "") : s.mode;
describe("independent V3 common acceptance", () => {
 it.each(["http://192.168.60.10:3773", "http://10.20.30.40:3773", "http://[fd12::1]:3773", "http://WORKSTATION.local:3773"])("selects a qualifying active primary LAN origin %s", url => {
  const state=resolveRemoteOpenState({...base,target:primary(url)});
  expect(hostOf(state)).toBe(new URL(url).hostname.replace(/^\[|\]$/g,""));
 });
 it.each(["https://proxy.example.com", "http://192.168.60.10/proxy", "http://u:p@192.168.60.10:3773", "http://192.168.60.10:3773/?route=proxy", "javascript:alert(1)"])("preserves known fallback for nonqualifying origin %s", url => {
  expect(hostOf(resolveRemoteOpenState({...base,target:primary(url)}))).toBe("fallback.tail0000.ts.net");
 });
 it("preserves relay fallback",()=>{
  expect(hostOf(resolveRemoteOpenState({...base,target:new RelayConnectionTarget({environmentId,label:"synthetic"})}))).toBe("fallback.tail0000.ts.net");
 });
 it("preserves explicit SSH alias",()=>{
  const state=resolveRemoteOpenState({...base,target:new SshConnectionTarget({environmentId,label:"synthetic",connectionId:"ssh-test"}),sshTarget:{alias:"workstation-alias",username:null}});
  expect(hostOf(state)).toBe("workstation-alias");
 });
 it("keeps desktop owned primary local",()=>{
  expect(resolveRemoteOpenState({...base,target:primary("http://172.29.112.1:3773"),isDesktopRenderer:true})).toEqual({mode:"local-exec"});
 });
 it.each(["host/path", "host@evil", "host#fragment", "host\nother", "-oProxyCommand=bad"])("rejects unsafe destination %s",host=>{
  expect(resolveRemoteOpenState({...base,target:new SshConnectionTarget({environmentId,label:"synthetic",connectionId:"ssh-test"}),sshTarget:{alias:host,username:null}})).toEqual({mode:"remote-unavailable"});
 });
 it("preserves Windows login and escapes file delimiters",()=>{
  expect(buildRemoteOpenUrl({editor:"vscode",host:"workstation",username:"DOMAIN\\dev user",absolutePath:"C:\\Work\\one #?.md",isFile:true})).toBe("vscode://vscode-remote/ssh-remote+DOMAIN%5Cdev%20user%40workstation/C%3A/Work/one%20%23%3F.md:1:1");
 });
});

describe("independent active-route and Windows regressions",()=>{
 it("uses the prepared bearer LAN route rather than the first advertised host",()=>{
  const input={...base,target:new BearerConnectionTarget({environmentId,label:"synthetic",connectionId:"direct-test"}),httpBaseUrl:"http://192.168.60.11:3773"};
  expect(hostOf(resolveRemoteOpenState(input))).toBe("192.168.60.11");
 });
 it.each(["DOMAIN\\dev", "dev user"])("preserves a valid Windows SSH username %s",username=>{
  const state=resolveRemoteOpenState({...base,target:new SshConnectionTarget({environmentId,label:"synthetic",connectionId:"ssh-test"}),sshTarget:{alias:"workstation-alias",username}});
  expect(state.mode).toBe("remote-links");
  if(state.mode!=="remote-links")throw new Error("expected usable alias");
  expect(buildRemoteOpenUrl({editor:"vscode",...state.host,absolutePath:"C:\\Work"})).toBe(`vscode://vscode-remote/ssh-remote+${encodeURIComponent(username+"@workstation-alias")}/C%3A/Work`);
 });
 it.each(["http://[::ffff:127.0.0.1]:3773", "http://[fe80::1234]:3773"])("keeps fallback for unusable unscoped or mapped-loopback target %s",url=>{
  const input={...base,target:new BearerConnectionTarget({environmentId,label:"synthetic",connectionId:"direct-test"}),httpBaseUrl:url};
  expect(hostOf(resolveRemoteOpenState(input))).toBe("fallback.tail0000.ts.net");
 });
});

