import {BearerConnectionTarget} from "@t3tools/client-runtime/connection";
import {EnvironmentId} from "@t3tools/contracts";
import {it,expect} from "vite-plus/test";
import {resolveRemoteOpenState} from "./remoteOpen";
it.each(["http://host.localhost:3773", "http://host.localhost.:3773"])("retains known remote fallback for loopback namespace %s",httpBaseUrl=>{
 const target=new BearerConnectionTarget({environmentId:EnvironmentId.make("v3-review-synthetic"),label:"synthetic",connectionId:"direct-test"});
 const state=resolveRemoteOpenState({target,httpBaseUrl,sshTarget:null,isDesktopRenderer:false,remoteOpenTargets:[{kind:"tailscale",host:"fallback.tail0000.ts.net",username:"dev"}]});
 expect(state).toEqual({mode:"remote-links",host:{kind:"tailscale",host:"fallback.tail0000.ts.net",username:"dev"}});
});

shared-alias-regression.test.ts.text:
import {SshConnectionTarget} from "@t3tools/client-runtime/connection";
import {EnvironmentId} from "@t3tools/contracts";
import {it,expect} from "vite-plus/test";
import {resolveRemoteOpenState} from "./remoteOpen";
it("preserves the supported concrete SSH config alias dev+gpu",()=>{
 const target=new SshConnectionTarget({environmentId:EnvironmentId.make("v3-review-synthetic"),label:"synthetic",connectionId:"ssh-test"});
 expect(resolveRemoteOpenState({target,sshTarget:{alias:"dev+gpu",username:null},isDesktopRenderer:false,remoteOpenTargets:[{kind:"tailscale",host:"fallback.tail0000.ts.net"}]})).toEqual({mode:"remote-links",host:{kind:"ssh-alias",host:"dev+gpu"}});
});
